    Zk = 7 + TOPP[Sk] + BOTP[Sk] - (Zx - 7);       /* shorts the other phase of Sk */
    Zn = 7 + TOPP[Sn] + BOTP[Sn] - (Zx - 7);       /* shorts the other phase of Sn */
