      addHalf(Z0A[s], d0/4);  addSlot(Sk, dk/2);  addSlot(Sn, dn/2);  addSlot(Z0B[s], d0/2);
      addSlot(Sn, dn/2);  addSlot(Sk, dk/2);  addHalf(Z0A[s], d0/4);
